referenceSolutions.javascript:
export function longestCommonPrefix(words          )         {
  if (words.length === 0) return ''; let prefix = words[0]; for (const word of words.slice(1)) while (!word.startsWith(prefix)) prefix = prefix.slice(0,-1); return prefix;
}

